import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const read = file => readFileSync(file, 'utf8');
const manifest = JSON.parse(read('manifest.webmanifest'));
const login = read('login.html');
const index = read('index.html');
const pwa = read('pwa.js');
const loginCss = read('login.css');
const appCss = read('styles.css');
const sw = read('sw.js');
const apache = read('.htaccess');
const deploy = read('.github/workflows/deploy.yml');

assert.equal(manifest.display, 'standalone');
assert.equal(manifest.display_override[0], 'standalone');
assert.equal(manifest.prefer_related_applications, false);
assert(manifest.icons.some(icon => icon.sizes === '192x192' && icon.type === 'image/png'));
assert(manifest.icons.some(icon => icon.sizes === '512x512' && icon.type === 'image/png'));
assert(manifest.icons.some(icon => icon.purpose === 'maskable'));
for (const html of [login, index]) {
  assert(/manifest\.webmanifest\?v=\d+/.test(html), 'manifest must be versioned on all entry points');
  assert(/pwa\.js\?v=\d+/.test(html), 'PWA handler must be versioned on all entry points');
  assert(/pwa\.css\?v=\d+/.test(html), 'PWA styles must be versioned on all entry points');
}
assert(/login\.css\?v=\d+/.test(login), 'login styles must be versioned');
assert(/styles\.css\?v=\d+/.test(index), 'app styles must be versioned');
assert(/const CACHE = 'uvoria-v\d+'/.test(sw), 'service worker cache must be versioned');
assert(loginCss.includes('Tablet auth layout and touch ergonomics v46'));
assert(appCss.includes('Tablet touch and scroll access v76'));
assert(pwa.includes('showInstallGuide'));
assert(pwa.includes('isYandex()'));
assert(pwa.includes('beforeinstallprompt'));
assert(apache.includes('application/manifest+json .webmanifest'));
assert(pwa.includes("window.addEventListener('appinstalled', () => markInstalled({ persist: true }))"));
assert(pwa.includes('pwaInstallConfirmed'));
assert(pwa.includes('urovia-pwa-installed-v1'), 'legacy install key must be cleared for users upgrading from old builds');
assert(pwa.includes('urovia-pwa-installed-v2'), 'confirmed install state must persist across ordinary browser reopen');
assert(pwa.includes('clearLegacyInstalledFlag()'));
assert(pwa.includes('getInstalledRelatedApps'), 'supported browsers should detect an already-installed PWA');
assert(Array.isArray(manifest.related_applications) && manifest.related_applications.some(app => app.platform === 'webapp' && app.url.includes('manifest.webmanifest')));
assert(pwa.includes("install.className = 'pwa-install-button';"), 'install action must be visible by default in an ordinary browser');
assert(pwa.includes('Обновить UROVIA'), 'PWA update action must be clearly distinguished from assignment completion');
assert(pwa.includes('pwaUpdateToast'), 'PWA must render one update notification');
assert(!pwa.includes('pwaUpdateShortcut'), 'PWA must not render a duplicate update shortcut');
assert(pwa.includes('checkForReleaseUpdate'), 'PWA must detect deploy releases independently from Service Worker byte changes');
assert(pwa.includes('UPDATE_CHECK_INTERVAL_MS'), 'PWA must periodically check for a new release');
assert(pwa.includes("window.addEventListener('focus'"), 'PWA must check updates after returning to the app');
assert(index.includes('name="urovia-release" content="dev"'), 'app entry must expose a release marker for deployment stamping');
assert(login.includes('name="urovia-release" content="dev"'), 'login entry must expose a release marker for deployment stamping');
assert(deploy.includes('version.json'), 'deployment must publish a version marker on every release');
assert(deploy.includes('Stamp release metadata'), 'deployment must stamp the current commit into entry pages');
assert(read('pwa.css').includes('Single release update toast v51'), 'single update notification must have responsive styling');
assert(!read('pwa.css').includes('.pwa-update-shortcut'), 'duplicate update shortcut styling must be removed');
assert(pwa.includes('urovia:assessment-state'), 'PWA updates must listen to assessment state');
assert(pwa.includes('assessmentUiVisible'), 'PWA update toast must be deferred while a student assessment is visible');
assert(pwa.includes('Android · установить как приложение'), 'Android install button should be device-aware');
assert(pwa.includes('Готово, установлено ✓'), 'iOS guide must include explicit post-install confirmation');
assert(pwa.includes('APK-файл для этого не требуется'), 'Android guide should explain browser app installation');
assert(pwa.includes("if (isIOS()) {\n        showInstallGuide();"), 'iOS button must open installation instructions directly');
assert(pwa.includes('Открываем установку…'), 'native Android prompt should show clear progress state');
assert(pwa.includes("typeof navigator.install === 'function'"), 'Android should detect the modern Web Install API when available');
assert(pwa.includes('await navigator.install()'), 'Android should invoke the modern Web Install API from the install action');
assert(read('pwa.css').includes('Device-aware install action v47'), 'tablet install controls must include device-aware styling');
assert(read('pwa.css').includes('@media (min-width:641px) and (max-width:1180px) and (pointer:coarse)'), 'tablet PWA install button must keep the base touch layout');
assert(read('pwa.css').includes('Android tablet install CTA v48'), 'Android tablets must have a larger install CTA');
assert(read('pwa.css').includes('@media (min-width:641px) and (max-width:1366px) and (pointer:coarse)'), 'Android tablet install CTA must cover common tablet widths');
console.log('Tablet layout and cross-browser PWA regression checks OK');
